<template>
  <teleport to="body">
    <transition name="detail-panel-backdrop">
      <div
        v-if="modelValue"
        class="detail-panel-backdrop"
        @click="close"
      />
    </transition>
    <transition name="detail-panel-slide">
      <div
        v-if="modelValue"
        class="detail-panel"
