<template>
  <div class="docnet-org-chart">
    <div class="row items-center justify-end q-mb-sm q-gutter-sm">
        <!-- Search -->
        <q-input
          v-model="searchQuery"
          :placeholder="$t('search_agents')"
          outlined
          dense
          clearable
          class="org-search-input"
        >
          <template #prepend>
            <q-icon name="search" />
          </template>
        </q-input>

        <!-- Zoom controls -->
        <div class="org-zoom-controls">
          <q-btn flat dense round icon="remove" size="sm" @click="zoomOut" />
          <span class="zoom-label">{{ Math.round(zoom * 100) }}%</span>
          <q-btn flat dense round icon="add" size="sm" @click="zoomIn" />
          <q-btn flat dense round icon="fit_screen" size="sm" @click="resetView" />
        </div>
    </div>

    <div v-if="loading" class="text-center q-pa-xl">
      <q-spinner-dots color="primary" size="40px" />
    </div>

    <div v-else-if="profiles.length === 0" class="text-center q-pa-xl">
      <q-icon name="account_tree" size="64px" color="grey-5" />
      <p class="q-mt-md text-grey-6">{{ $t('no_agents') }}</p>
    </div>

    <div
      v-else
      ref="viewport"
      class="org-viewport"
      @wheel.prevent="onWheel"
      @mousedown="onPanStart"
      @mousemove="onPanMove"
      @mouseup="onPanEnd"
      @mouseleave="onPanEnd"
    >
      <!-- Root drop zone (visible during drag) -->
      <div
        class="org-root-drop-zone"
        :class="{ 'org-root-drop-zone--active': isDragging }"
        @dragover.prevent="onRootDragOver"
        @dragenter.prevent="rootDropHighlight = true"
        @dragleave="rootDropHighlight = false"
        @drop="onRootDrop"
      >
        <q-icon name="vertical_align_top" size="20px" />
        <span>Drop here to make root agent</span>
      </div>

      <div
        class="org-canvas"
        :style="canvasStyle"
      >
        <div class="org-tree">
          <!-- Router at the top (only when multiple orchestrators) -->
          <div v-if="routerProfile && orchestratorProfiles.length > 1" class="org-router-group">
            <OrgChartNode
              :profile="routerProfile"
              :all-profiles="routerTree"
              :search-query="searchQuery"
              @navigate="navigateToAgent"
              @edit-node="openEditDialog"
              @reparent="handleReparent"
            />
          </div>

          <!-- Single orchestrator (no router needed) -->
          <div v-else-if="orchestratorProfiles.length === 1" class="org-orchestrator-group">
            <OrgChartNode
              :profile="orchestratorProfiles[0]"
              :all-profiles="singleOrchestratorTree"
              :search-query="searchQuery"
              @navigate="navigateToAgent"
              @edit-node="openEditDialog"
              @reparent="handleReparent"
            />
          </div>

          <!-- No orchestrator (fallback) -->
          <template v-if="orchestratorProfiles.length === 0">
            <OrgChartNode
              v-for="root in rootProfiles"
              :key="root.agent.id"
              :profile="root"
              :all-profiles="profiles"
              :search-query="searchQuery"
              @navigate="navigateToAgent"
              @edit-node="openEditDialog"
              @reparent="handleReparent"
            />
          </template>

          <!-- Unassigned agents -->
          <div v-if="unassignedAgents.length > 0 && orchestratorProfiles.length > 0" class="org-unassigned-group">
            <div class="unassigned-label">Unassigned Agents</div>
            <div class="unassigned-agents">
              <OrgChartNode
                v-for="agent in unassignedAgents"
                :key="agent.agent.id"
                :profile="agent"
                :all-profiles="profiles"
                :search-query="searchQuery"
                @navigate="navigateToAgent"
                @edit-node="openEditDialog"
                @reparent="handleReparent"
              />
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Search results hint -->
    <div v-if="searchQuery && matchCount > 0" class="org-search-hint q-mt-sm text-caption text-grey-6">
      {{ matchCount }} {{ matchCount === 1 ? 'agent' : 'agents' }} matching "{{ searchQuery }}"
    </div>
    <div v-else-if="searchQuery && matchCount === 0" class="org-search-hint q-mt-sm text-caption text-negative">
      No agents matching "{{ searchQuery }}"
    </div>

    <!-- Agent detail panel -->
    <DetailPanel v-model="showAgentPanel" :title="previewProfile ? previewProfile.agent.name : $t('agent_details')">
      <AgentDetailPreview
        :profile="previewProfile"
        :all-profiles="profiles"
        @open-full="goToAgent"
      />
    </DetailPanel>

    <OrgNodeEditDialog
      v-model="showEditDialog"
      :profile="editingProfile"
      :all-profiles="profiles"
      @saved="agentStore.fetchProfiles(true)"
    />
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { useDocNetAgentStore } from 'src/store/DocNet/docnet-agents.store';
import { storeToRefs } from 'pinia';
import type { DocNetAgentProfile } from 'src/@types/docnet';
import OrgChartNode from './components/OrgChartNode.vue';
import OrgNodeEditDialog from './components/OrgNodeEditDialog.vue';
import DetailPanel from '../shared/DetailPanel.vue';
import AgentDetailPreview from '../shared/AgentDetailPreview.vue';

function wouldCreateCycle(
  agentId: string,
  newParentId: string | null,
  profiles: DocNetAgentProfile[],
): boolean {
  if (!newParentId) return false;
  let current: string | undefined = newParentId;
  while (current) {
    if (current === agentId) return true;
    const parent = profiles.find((p) => p.agent.id === current);
    current = parent?.reports_to || undefined;
  }
  return false;
}

export default defineComponent({
  name: 'DocNetOrgChart',

  components: {
    OrgChartNode,
    OrgNodeEditDialog,
    DetailPanel,
    AgentDetailPreview,
  },

  setup() {
    const agentStore = useDocNetAgentStore();
    const { profiles: allProfiles, loading } = storeToRefs(agentStore);
    return { agentStore, allProfiles, loading };
  },

  data() {
    return {
      searchQuery: '',
      zoom: 1,
      panX: 0,
      panY: 0,
      isPanning: false,
      panStartX: 0,
      panStartY: 0,
      showAgentPanel: false,
      previewProfile: null as DocNetAgentProfile | null,
      showEditDialog: false,
      editingProfile: null as DocNetAgentProfile | null,
      isDragging: false,
      rootDropHighlight: false,
    };
  },

  computed: {
    profiles(): DocNetAgentProfile[] {
      return this.allProfiles.filter((p) => p.agent.is_enabled);
    },

    routerProfile(): DocNetAgentProfile | null {
      return this.profiles.find((p) => p.role === 'router') || null;
    },

    orchestratorProfiles(): DocNetAgentProfile[] {
      return this.profiles.filter((p) => p.role === 'orchestrator');
    },

    /**
     * Expand agents with array reports_to into one entry per parent.
     * This lets the tree component show the same agent under multiple orchestrators.
     */
    expandedProfiles(): DocNetAgentProfile[] {
      const result: DocNetAgentProfile[] = [];
      for (const p of this.profiles) {
        if (Array.isArray(p.reports_to) && p.reports_to.length > 0) {
          for (const parentId of p.reports_to) {
            result.push({ ...p, reports_to: parentId });
          }
        } else {
          result.push(p);
        }
      }
      return result;
    },

    /** Agents that are not router/orchestrator and have no reports_to set */
    unassignedAgents(): DocNetAgentProfile[] {
      return this.profiles.filter(
        (p) => p.role !== 'router' && p.role !== 'orchestrator'
          && !p.reports_to
      );
    },

    /** Fallback root profiles (no orchestrator exists) */
    rootProfiles(): DocNetAgentProfile[] {
      return this.profiles.filter((p) => !p.reports_to && p.role !== 'router');
    },

    /**
     * Tree for router: router at top, orchestrators as children,
     * agents under their orchestrator.
     */
    routerTree(): DocNetAgentProfile[] {
      if (!this.routerProfile) return this.expandedProfiles;
      const routerId = this.routerProfile.agent.id;
      return this.expandedProfiles
        .filter((p) => p.role !== 'router')
        .map((p) => {
          if (p.role === 'orchestrator' && !p.reports_to) {
            return { ...p, reports_to: routerId };
          }
          return p;
        })
        .concat([this.routerProfile]);
    },

    /**
     * Tree for single orchestrator: all non-router agents
     * without reports_to become children of the orchestrator.
     */
    singleOrchestratorTree(): DocNetAgentProfile[] {
      if (this.orchestratorProfiles.length !== 1) return this.expandedProfiles;
      const orchId = this.orchestratorProfiles[0].agent.id;
      return this.expandedProfiles
        .filter((p) => p.role !== 'router')
        .map((p) => {
          if (!p.reports_to && p.agent.id !== orchId && p.role !== 'orchestrator') {
            return { ...p, reports_to: orchId };
          }
          return p;
        });
    },

    canvasStyle(): Record<string, string> {
      return {
        transform: `translate(${this.panX}px, ${this.panY}px) scale(${this.zoom})`,
        transformOrigin: '0 0',
      };
    },

    matchCount(): number {
      if (!this.searchQuery) return 0;
      const q = this.searchQuery.toLowerCase();
      return this.profiles.filter(
        (p) =>
          p.agent.name.toLowerCase().includes(q) ||
          p.role.toLowerCase().includes(q),
      ).length;
    },
  },

  mounted() {
    this.agentStore.fetchProfiles();
    document.addEventListener('dragstart', this.onGlobalDragStart);
    document.addEventListener('dragend', this.onGlobalDragEnd);
  },

  beforeUnmount() {
    document.removeEventListener('dragstart', this.onGlobalDragStart);
    document.removeEventListener('dragend', this.onGlobalDragEnd);
  },

  methods: {
    onGlobalDragStart() {
      this.isDragging = true;
    },

    onGlobalDragEnd() {
      this.isDragging = false;
      this.rootDropHighlight = false;
    },

    zoomIn() {
      this.zoom = Math.min(this.zoom + 0.15, 2);
    },

    zoomOut() {
      this.zoom = Math.max(this.zoom - 0.15, 0.4);
    },

    resetView() {
      this.zoom = 1;
      this.panX = 0;
      this.panY = 0;
    },

    onWheel(e: WheelEvent) {
      const delta = e.deltaY > 0 ? -0.08 : 0.08;
      this.zoom = Math.min(Math.max(this.zoom + delta, 0.4), 2);
    },

    onPanStart(e: MouseEvent) {
      if (e.button !== 0) return;
      this.isPanning = true;
      this.panStartX = e.clientX - this.panX;
      this.panStartY = e.clientY - this.panY;
    },

    onPanMove(e: MouseEvent) {
      if (!this.isPanning) return;
      this.panX = e.clientX - this.panStartX;
      this.panY = e.clientY - this.panStartY;
    },

    onPanEnd() {
      this.isPanning = false;
    },

    navigateToAgent(id: string) {
      const profile = this.profiles.find((p) => p.agent.id === id);
      if (profile) {
        this.previewProfile = profile;
        this.showAgentPanel = true;
      }
    },

    goToAgent(id: string) {
      this.showAgentPanel = false;
      this.$router.push('/doc-net/agents/' + id);
    },

    openEditDialog(profile: DocNetAgentProfile) {
      // Orchestrators and routers don't report to anyone — skip the dialog.
      if (profile.role === 'orchestrator' || profile.role === 'router') return;
      this.editingProfile = profile;
      this.showEditDialog = true;
    },

    async handleReparent({ childId, newParentId }: { childId: string; newParentId: string | null }) {
      if (childId === newParentId) return;

      if (wouldCreateCycle(childId, newParentId, this.profiles)) {
        notify.error('Cannot move: this would create a circular hierarchy.', { duration: 3000 });
        return;
      }

      const profile = this.profiles.find((p) => p.agent.id === childId);
      if (!profile) return;

      try {
        // Use the dedicated per-org endpoint via the store action. The
        // previous implementation went through ``updateAgentConfig``
        // (generic PUT) which, for system agents, silently clobbered the
        // shared ``agents.config`` row with this org's ``reports_to``.
        await this.agentStore.updateAgentReportsTo(childId, newParentId);
        await this.agentStore.fetchProfiles(true);

        const targetName = newParentId
          ? this.profiles.find((p) => p.agent.id === newParentId)?.agent.name || 'parent'
          : 'root';
        notify.success(`${profile.agent.name} moved to ${targetName}.`);
      } catch (e: any) {
        console.error('[OrgChart] Reparent failed:', e, e?.response?.status, e?.response?.data);
        const detail = e?.response?.data?.detail || e?.message || 'Failed to update hierarchy.';
        notify.error(detail);
      }
    },

    onRootDragOver(e: DragEvent) {
      if (e.dataTransfer) {
        e.dataTransfer.dropEffect = 'move';
      }
      this.rootDropHighlight = true;
    },

    onRootDrop(e: DragEvent) {
      e.preventDefault();
      this.rootDropHighlight = false;
      this.isDragging = false;
      const childId = e.dataTransfer?.getData('agent-id');
      if (childId) {
        this.handleReparent({ childId, newParentId: null });
      }
    },
  },
});
</script>

