<template>
  <div class="org-chart-node-group">
    <!-- Node card -->
    <q-card
      class="org-chart-node cursor-pointer"
      :class="{
        'org-chart-node--highlighted': isMatch,
        'org-chart-node--dimmed': isDimmed,
        'org-chart-node--root': isRoot,
        'org-chart-node--drop-target': isDropTarget,
        'org-chart-node--system': profile.agent.is_system,
        'org-chart-node--custom': !profile.agent.is_system,
      }"
      flat
      bordered
      draggable="true"
      @click="$emit('navigate', profile.agent.id)"
      @contextmenu.prevent="showContextMenu = true"
      @dragstart="onDragStart"
      @dragover.prevent="onDragOver"
      @dragenter.prevent="isDropTarget = true"
      @dragleave="isDropTarget = false"
      @drop="onDrop"
    >
      <!-- Edit button (visible on hover) — only specialists can edit reports_to -->
      <q-btn
        v-if="canEditPosition"
        class="org-node-edit-btn"
        flat
        dense
        round
        size="xs"
        icon="edit"
        @click.stop="$emit('edit-node', profile)"
      />

      <q-card-section class="row items-center q-gutter-sm q-pa-sm no-wrap">
        <div class="org-node-avatar-wrapper">
          <q-avatar
            :size="isRoot ? '36px' : '30px'"
            :color="statusColor"
            text-color="white"
            :font-size="isRoot ? '18px' : '15px'"
          >
            <q-icon name="smart_toy" />
          </q-avatar>
          <span v-if="isActive" class="org-node-pulse" />
        </div>
        <div class="col">
          <div
            class="org-node-name"
            :class="{ 'text-subtitle2': isRoot, 'text-body2': !isRoot }"
          >
            {{ profile.agent.name }}
          </div>
          <div class="text-caption text-grey-6 text-capitalize">{{ profile.role }}</div>
        </div>
        <div class="column items-end q-gutter-xs">
          <q-badge
            v-if="delegation && delegation.is_delegating"
            color="info"
            text-color="white"
            dense
            class="text-caption"
          >
            <q-icon name="call_split" size="10px" class="q-mr-xs" />
            {{ delegation.pending_children }}
          </q-badge>
          <q-btn
            v-if="children.length > 0"
            flat
            dense
            round
            size="xs"
            :icon="expanded ? 'expand_less' : 'expand_more'"
            @click.stop="expanded = !expanded"
          />
        </div>
      </q-card-section>

      <!-- Context menu -->
      <q-menu v-model="showContextMenu" context-menu>
        <q-list dense style="min-width: 180px">
          <q-item v-if="canEditPosition" clickable v-close-popup @click="$emit('edit-node', profile)">
            <q-item-section side><q-icon name="edit" size="18px" /></q-item-section>
            <q-item-section>{{ $t('edit_reporting') }}</q-item-section>
          </q-item>
          <q-item clickable v-close-popup @click="$emit('reparent', { childId: profile.agent.id, newParentId: null })">
            <q-item-section side><q-icon name="link_off" size="18px" /></q-item-section>
            <q-item-section>Remove from hierarchy</q-item-section>
          </q-item>
          <q-separator />
          <q-item clickable v-close-popup @click="$emit('navigate', profile.agent.id)">
            <q-item-section side><q-icon name="visibility" size="18px" /></q-item-section>
            <q-item-section>View Details</q-item-section>
          </q-item>
        </q-list>
      </q-menu>
    </q-card>

    <!-- Vertical connector from parent to children -->
    <div v-if="children.length > 0 && expanded" class="org-connector-down" />

    <!-- Children -->
    <div v-if="children.length > 0 && expanded" class="org-chart-children" :class="{ 'has-multiple': children.length > 1 }">
      <OrgChartNode
        v-for="child in children"
        :key="child.agent.id"
        :profile="child"
        :all-profiles="allProfiles"
        :search-query="searchQuery"
        @navigate="$emit('navigate', $event)"
        @edit-node="$emit('edit-node', $event)"
        @reparent="$emit('reparent', $event)"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { DocNetAgentProfile, DocNetDelegationStatus } from 'src/@types/docnet';
import { useDocNetAgentStore } from 'src/store/DocNet/docnet-agents.store';

export default defineComponent({
  name: 'OrgChartNode',

  props: {
    profile: {
      type: Object as PropType<DocNetAgentProfile>,
      required: true,
    },
    allProfiles: {
      type: Array as PropType<DocNetAgentProfile[]>,
      required: true,
    },
    searchQuery: {
      type: String,
      default: '',
    },
  },

  emits: ['navigate', 'edit-node', 'reparent'],

  setup() {
    const agentStore = useDocNetAgentStore();
    return { agentStore };
  },

  data() {
    return {
      expanded: true,
      showContextMenu: false,
      isDropTarget: false,
    };
  },

  computed: {
    isRoot(): boolean {
      return !this.profile.reports_to;
    },

    /** Only specialists can edit reports_to — orchestrators/routers are the top of the hierarchy */
    canEditPosition(): boolean {
      return this.profile.role !== 'orchestrator' && this.profile.role !== 'router';
    },

    isActive(): boolean {
      const hs = this.profile.heartbeat_status;
      return hs === 'working' || hs === 'awake' || this.profile.workload_percent > 0;
    },

    children(): DocNetAgentProfile[] {
      return this.allProfiles.filter(
        (p) => p.reports_to === this.profile.agent.id,
      );
    },

    statusColor(): string {
      if (this.isActive) return 'primary';
      return 'blue-grey';
    },


    isMatch(): boolean {
      if (!this.searchQuery) return false;
      const q = this.searchQuery.toLowerCase();
      return (
        this.profile.agent.name.toLowerCase().includes(q) ||
        this.profile.role.toLowerCase().includes(q)
      );
    },

    isDimmed(): boolean {
      return !!this.searchQuery && !this.isMatch;
    },

    delegation(): DocNetDelegationStatus | undefined {
      return this.agentStore.getDelegationStatus(this.profile.agent.id);
    },
  },

  methods: {
    onDragStart(e: DragEvent) {
      if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('agent-id', this.profile.agent.id);
      }
    },

    onDragOver(e: DragEvent) {
      if (e.dataTransfer) {
        e.dataTransfer.dropEffect = 'move';
      }
      this.isDropTarget = true;
    },

    onDrop(e: DragEvent) {
      e.stopPropagation();
      this.isDropTarget = false;
      const childId = e.dataTransfer?.getData('agent-id');
      if (childId && childId !== this.profile.agent.id) {
        this.$emit('reparent', { childId, newParentId: this.profile.agent.id });
      }
    },
  },
});
</script>

