<template>
  <div v-if="profile" class="agent-detail-preview">
    <!-- Header: Avatar + Status -->
    <div class="preview-agent-header row items-center q-gutter-sm q-mb-md">
      <div class="preview-avatar-wrapper">
        <q-avatar
          size="42px"
          :color="isAgentActive ? 'primary' : 'blue-grey'"
          text-color="white"
          font-size="22px"
        >
          <q-icon name="smart_toy" />
        </q-avatar>
        <span v-if="isAgentActive" class="preview-pulse" />
      </div>
      <div class="col">
        <div class="preview-agent-name">{{ profile.agent.name }}</div>
        <div class="text-caption text-grey-6 text-capitalize">
          {{ profile.approval_mode }} approval
        </div>
      </div>
      <q-badge
        :color="statusBadgeColor"
        :label="statusBadgeLabel"
      />
    </div>

    <!-- Skills -->
    <div v-if="profile.skills_summary && profile.skills_summary.length" class="preview-section">
      <div class="preview-section__label">{{ $t('skills') }}</div>
      <div class="row q-gutter-xs">
        <q-chip
          v-for="skill in profile.skills_summary"
          :key="skill"
          size="sm"
          outline
          color="primary"
          :label="skill"
          dense
        />
      </div>
    </div>

    <!-- Reporting line -->
    <div class="preview-section">
      <div class="preview-section__label">{{ $t('reporting_line') }}</div>
      <div v-if="reportsToProfiles.length > 0" class="q-mb-xs">
        <span class="text-caption text-grey-6">{{ $t('reports_to') }}: </span>
        <span class="text-weight-medium">{{ reportsToProfiles.map(p => p.agent.name).join(', ') }}</span>
      </div>
      <div v-if="directReports.length > 0">
        <span class="text-caption text-grey-6">{{ $t('direct_reports') }} ({{ directReports.length }}): </span>
        <span class="text-caption">{{ directReports.map(r => r.agent.name).join(', ') }}</span>
      </div>
      <div v-if="reportsToProfiles.length === 0 && directReports.length === 0" class="text-caption text-grey-5">
        {{ $t('no_reporting_line') }}
      </div>
    </div>

    <!-- Open full profile -->
    <div class="preview-section q-mt-md">
      <f-btn
        appearance="outline"
        :label="$t('agent_details')"
        icon="open_in_new"
        size="sm"
        class="full-width"
        @click="$emit('open-full', profile.agent.id)"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { DocNetAgentProfile } from 'src/@types/docnet';

export default defineComponent({
  name: 'AgentDetailPreview',

  props: {
    profile: {
      type: Object as PropType<DocNetAgentProfile | null>,
      default: null,
    },
    allProfiles: {
      type: Array as PropType<DocNetAgentProfile[]>,
      default: () => [],
    },
  },

  emits: ['open-full'],

  computed: {
    isAgentActive(): boolean {
      const hs = this.profile?.heartbeat_status;
      return hs === 'working' || hs === 'awake';
    },

    statusBadgeColor(): string {
      const hs = this.profile?.heartbeat_status;
      if (hs === 'working' || hs === 'awake') return 'positive';
      if (hs === 'error') return 'negative';
      return 'grey-5';
    },

    statusBadgeLabel(): string {
      const hs = this.profile?.heartbeat_status;
      if (hs === 'working') return this.$t('agent_working');
      if (hs === 'awake') return this.$t('agent_awake');
      if (hs === 'error') return this.$t('agent_error');
      return this.$t('agent_idle');
    },

    /** Agents this profile reports to (supports single string or array) */
    reportsToProfiles(): DocNetAgentProfile[] {
      const raw = this.profile?.reports_to;
      if (!raw) return [];
      const ids: string[] = Array.isArray(raw) ? raw.filter(Boolean) : [raw];
      return ids
        .map((id) => this.allProfiles.find((p) => p.agent.id === id))
        .filter((p): p is DocNetAgentProfile => !!p);
    },

    directReports(): DocNetAgentProfile[] {
      if (!this.profile) return [];
      const myId = this.profile.agent.id;
      return this.allProfiles.filter((p) => {
        const raw = p.reports_to;
        if (!raw) return false;
        if (Array.isArray(raw)) return raw.includes(myId);
        return raw === myId;
      });
    },
  },
});
</script>

