<template>
  <q-dialog :model-value="modelValue" @update:model-value="$emit('update:modelValue', $event)">
    <q-card style="min-width: 400px; max-width: 480px">
      <q-card-section class="row items-center q-pb-none">
        <div class="text-h6">{{ $t('edit_reporting') }}</div>
        <q-space />
        <q-btn icon="close" flat round dense v-close-popup />
      </q-card-section>

      <q-card-section v-if="profile">
        <div class="text-subtitle1 text-weight-medium q-mb-xs">
          {{ profile.agent.name }}
        </div>
        <div class="text-caption text-grey-7 q-mb-md">
          {{ $t('org_chart_reports_to_hint') }}
        </div>

        <q-select
          v-model="localReportsTo"
          :options="reportsToOptions"
          multiple
          use-chips
          dense
          outlined
          emit-value
          map-options
          clearable
          :label="$t('reports_to')"
        />
      </q-card-section>

      <q-card-actions align="right">
        <q-btn flat :label="$t('cancel')" v-close-popup />
        <q-btn color="primary" :label="$t('save')" :loading="saving" @click="save" />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, type PropType } from 'vue';
import type { DocNetAgentProfile } from 'src/@types/docnet';
import { useDocNetAgentStore } from 'src/store/DocNet/docnet-agents.store';

export default defineComponent({
  name: 'OrgNodeEditDialog',

  props: {
    modelValue: { type: Boolean, default: false },
    profile: { type: Object as PropType<DocNetAgentProfile | null>, default: null },
    allProfiles: { type: Array as PropType<DocNetAgentProfile[]>, default: () => [] },
  },

  emits: ['update:modelValue', 'saved'],

  data() {
    return {
      localReportsTo: [] as string[],
      saving: false,
    };
  },

  computed: {
    /** Only orchestrators can be reported to */
    reportsToOptions(): { label: string; value: string }[] {
      return this.allProfiles
        .filter((p) => p.role === 'orchestrator' && p.agent.id !== this.profile?.agent.id)
        .map((p) => ({ label: p.agent.name, value: p.agent.id }));
    },
  },

  watch: {
    modelValue(val: boolean) {
      if (val && this.profile) {
        const raw = this.profile.reports_to;
        if (Array.isArray(raw)) this.localReportsTo = raw.filter(Boolean);
        else if (typeof raw === 'string' && raw) this.localReportsTo = [raw];
        else this.localReportsTo = [];
      }
    },
  },

  methods: {
    async save() {
      if (!this.profile) return;
      this.saving = true;
      try {
        // Store as list when multiple, single string for one, null for none
        let reports_to: string | string[] | null;
        if (this.localReportsTo.length === 0) reports_to = null;
        else if (this.localReportsTo.length === 1) reports_to = this.localReportsTo[0];
        else reports_to = [...this.localReportsTo];

        // Route through the dedicated per-org endpoint via the store.
        // Going through the generic ``updateAgentConfig`` used to leak
        // this org's ``reports_to`` into the shared agent row for system
        // agents; the store action now uses ``/agents/{id}/reports-to``.
        const agentStore = useDocNetAgentStore();
        await agentStore.updateAgentReportsTo(this.profile.agent.id, reports_to);
        this.$emit('saved');
        this.$emit('update:modelValue', false);
      } catch (e: any) {
        console.error('[OrgNodeEditDialog] Save failed:', e);
        notify.error(e?.response?.data?.detail || 'Failed to save changes.', { duration: 3000 });
      } finally {
        this.saving = false;
      }
    },
  },
});
</script>
